// ============================================================
// WF7 — NO ALTERNATIVE FALLBACK
// Zero alternatives in the list at all.
// ============================================================
const data = $('Alternative Picker').first().json;
const now = new Date();

return [{ json: {
  status: 'no_alternative_available',
  workflow: 'WF7-NoAlternativeFallback',
  original_booking_id: data.booking_id,
  cancelled_provider: data.provider_name,
  service_type: data.service_type,
  location: data.location,
  booking_date: data.booking_date,
  user_email: data.user_email || '',
  user_name: data.user_name || 'Valued Customer',
  resolution: {
    refund: { eligible: true, amount_pkr: data.price_pkr, note: 'Full refund approved' },
    human_escalation: { required: true, ticket_id: `TKT-WF7-${Date.now()}`, reason: 'Zero alternatives after cancellation' },
    waitlist: { added: true, message: 'Added to waitlist. Will notify when provider available.' }
  },
  compensation: data.compensation,
  timestamp: now.toISOString(),

  // ── UI BUTTON CONTROL ─────────────────────────────────────────
  show_track_button: false,
  show_feedback_button: false,
  ui_actions: {
    show_track_button: false,
    show_cancel_button: false,
    show_report_button: false,
    show_feedback_button: false,
    primary_label: 'Cancelled — Refund Pending',
    secondary_label: null,
    reason: 'no_alternative_available_refund_issued'
  }
}}];

// ============================================================
// WF7 — NO SLOT FALLBACK
// New provider found but no slot available on that date.
// ============================================================
const data = $('Slot Selector').first().json;
const now = new Date();

const nextDays = [1, 2, 3].map(offset => {
  const d = new Date();
  d.setDate(d.getDate() + offset);
  const dateStr = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  const label = offset === 1 ? 'Tomorrow' : offset === 2 ? 'Day after tomorrow' : '3 days from now';
  return { date: dateStr, label, suggested_slots: ['09:00', '11:00', '14:00'] };
});

return [{ json: {
  status: 'no_slot_available',
  workflow: 'WF7-NoSlotFallback',
  original_booking_id: data.booking_id,
  cancelled_provider: data.provider_name,
  attempted_provider: data.next_best_provider?.name,
  service_type: data.service_type,
  location: data.location,
  booking_date: data.booking_date,
  alternate_dates: nextDays,
  compensation: data.compensation,
  user_email: data.user_email || '',
  user_name: data.user_name || 'Valued Customer',
  timestamp: now.toISOString(),

  // ── UI BUTTON CONTROL ─────────────────────────────────────────
  show_track_button: false,
  show_feedback_button: false,
  ui_actions: {
    show_track_button: false,
    show_cancel_button: false,
    show_report_button: false,
    show_feedback_button: false,
    primary_label: 'Pending Reschedule',
    secondary_label: null,
    reason: 'no_slot_available_awaiting_user_selection'
  }
}}];

// ============================================================
// WF7 — RESCHEDULE RECORD BUILDER
// Works for both provider cancel and user reschedule.
// ============================================================

const confirmData = $input.first().json;
const pickerData = $('Alternative Picker').first().json;
const intakeData = $('WF7 — Intake & Validator').first().json;

const newBookingId =
  confirmData.booking_id ||
  confirmData.receipt?.booking_id ||
  'N/A';

const newProvider = pickerData.next_best_provider;

function formatSlotLabel(time) {
  if (!time) return time;

  if (time.includes('AM') || time.includes('PM')) {
    return time;
  }

  const [h, m] = time.split(':').map(Number);

  const period = h >= 12 ? 'PM' : 'AM';
  const hour = h > 12 ? h - 12 : h === 0 ? 12 : h;

  return `${hour}:${String(m).padStart(2, '0')} ${period}`;
}

// ============================================================
// SLOT NORMALIZATION
// Handles:
// 1. selected_slot.time
// 2. selected_slot.label
// 3. WF4 appointment.time
// 4. WF4 appointment.time_label
// ============================================================

const selectedSlot = pickerData.selected_slot || {};
const appointment = confirmData.appointment || {};

const newSlotTime =
  selectedSlot.time ||
  selectedSlot.label ||
  appointment.time ||
  '';

const newSlotLabel =
  appointment.time_label ||
  formatSlotLabel(newSlotTime);

console.log('=== WF7 Reschedule Record ===');
console.log('Initiator:', intakeData.initiator);
console.log('New Booking:', newBookingId);
console.log('Slot Time:', newSlotTime);
console.log('Slot Label:', newSlotLabel);

return [{
  json: {
    status: 'rescheduled',
    workflow: 'WF7-AutoReschedule',
    initiator: intakeData.initiator,

    original_booking: {
      booking_id: intakeData.booking_id,
      provider: intakeData.provider_name,
      provider_id: intakeData.provider_id,
      slot: intakeData.slot,
      date: intakeData.booking_date
    },

    // provider_id stays unchanged in Supabase (original provider keeps booking in their list).
    // provider_action_locked=true + status=rescheduled tells frontend to show
    // [Cancelled / Feedback] buttons instead of [Track / Report / Cancel].
    provider_action_locked: true,
    tracking_locked: true,

    new_booking: {
      booking_id: newBookingId,

      provider:
        newProvider?.name ||
        confirmData.provider?.name ||
        '',

      provider_id:
        newProvider?.id ||
        newProvider?.place_id ||
        confirmData.provider?.id ||
        '',

      provider_score: newProvider?.computed_score,
      provider_rating: newProvider?.rating,

      slot: newSlotTime,
      slot_label: newSlotLabel,

      date: intakeData.booking_date,
      location: intakeData.location,
      price_pkr: intakeData.price_pkr,

      kept_original_time: pickerData.kept_original_time
    },

    // ── UI BUTTON CONTROL (matches WF5 pattern) ──────────────────
    // Frontend reads these fields to render the correct buttons per booking.
    // rescheduled + provider_action_locked → [Booking Reassigned] [Leave Feedback]
    show_track_button: false,
    show_feedback_button: true,
    ui_actions: {
      show_track_button: false,
      show_cancel_button: false,
      show_report_button: false,
      show_feedback_button: true,
      primary_label: 'Booking Reassigned',
      secondary_label: 'Leave Feedback',
      reason: 'booking_rescheduled_to_new_provider'
    },

        user_email: intakeData.user_email || '',
    user_name: intakeData.user_name || 'Valued Customer',

    compensation: pickerData.compensation,
    penalty_record: pickerData.penalty_record || null,

    customer_message:
      `Your booking with ${intakeData.provider_name} was cancelled. ` +
      `We have automatically reassigned your booking to ${newProvider?.name || 'a new provider'}.`,

    simulated_whatsapp:
      `⚠️ Provider Update — Khadmat AI\n\n` +
      `Previous Provider: ${intakeData.provider_name}\n` +
      `New Provider: ${newProvider?.name || 'N/A'}\n\n` +
      `🎫 New Booking ID: ${newBookingId}\n` +
      `📅 ${intakeData.booking_date} at ${newSlotLabel}\n` +
      `📍 ${intakeData.location}\n` +
      `💰 PKR ${intakeData.price_pkr}` +
      (
        pickerData.compensation?.eligible
          ? `\n🎁 Compensation: PKR ${pickerData.compensation.amount_pkr}`
          : ''
      ),

    timestamp: new Date().toISOString()
  }
}];

// ============================================================
// WF7 — SLOT SELECTOR
// Tries to keep the original time slot, falls back to first free.
// ============================================================
const wf4Response = $input.first().json;
const originalData = $('Alternative Picker').first().json;

const allSlots = wf4Response.slots || [];
const freeSlots = allSlots.filter(s => s.available);

if (freeSlots.length === 0) {
  return [{ json: {
    ...originalData,
    slot_selection: { success: false, reason: 'No available slots on original date for new provider' },
    wf4_slots_data: wf4Response
  }}];
}

const originalSlot = originalData.slot;

// Normalize helper for comparison
const normalize = (str = '') => str.toLowerCase().replace(/\s/g, '').trim();

const matchingOriginal = freeSlots.find(s =>
  normalize(s.label || s.time) === normalize(originalSlot) && s.available
);

const selectedSlot = matchingOriginal || freeSlots[0];

console.log('=== WF7 Slot Selector ===');
console.log('Original Slot:', originalSlot, '| Matched:', !!matchingOriginal, '| Selected:', selectedSlot?.time || selectedSlot?.label);

return [{ json: {
  ...originalData,
  selected_slot: selectedSlot,
  kept_original_time: !!matchingOriginal,
  free_slots_available: freeSlots.length,
  slot_selection: { success: true },
  wf4_slots_data: wf4Response
}}];

// ============================================================
// WF7 — ALTERNATIVE PICKER
// Shared by both provider cancel and user reschedule paths.
// Picks the highest-scored alternative provider.
// ============================================================
const data = $input.first().json;
const now = new Date();

const alternatives = data.alternatives || [];
const sorted = [...alternatives].sort((a, b) =>
  (b.computed_score || b.score || 0) - (a.computed_score || a.score || 0)
);

const nextBest = sorted.length > 0 ? sorted[0] : null;
const remaining = sorted.slice(1);

let compensation = { eligible: false, amount_pkr: 0, reason: '' };
if (data.is_urgent) {
  compensation = { eligible: true, amount_pkr: 250, reason: 'Urgent cancellation — PKR 250 credit on next booking.' };
} else if (data.hours_until_booking < 12) {
  compensation = { eligible: true, amount_pkr: 100, reason: 'Same-day cancellation. PKR 100 discount credit added.' };
}

console.log('=== WF7 Alternative Picker ===');
console.log('Initiator:', data.initiator, '| Next best:', nextBest?.name || 'None');

return [{ json: {
  ...data,
  next_best_provider: nextBest,
  remaining_alternatives: remaining,
  has_alternative: !!nextBest,
  compensation,
  picker_timestamp: now.toISOString()
}}];

// ============================================================
// WF7 — PENALTY ENGINE
// Only runs for provider cancellations.
// Applies a strike to the cancelling provider.
// ============================================================
const data = $('WF7 — Intake & Validator').first().json;
const now = new Date();

const existingCancellationRate = parseFloat(data.provider_cancellation_rate) || 0.08;
const isRepeatOffender = existingCancellationRate > 0.20;

const updatedCancellationRate = Math.min(1.0, parseFloat((existingCancellationRate + 0.05).toFixed(2)));
const blacklisted = updatedCancellationRate > 0.30 || isRepeatOffender;

const penaltyRecord = {
  provider_id: data.provider_id,
  provider_name: data.provider_name,
  previous_cancellation_rate: existingCancellationRate,
  updated_cancellation_rate: updatedCancellationRate,
  blacklisted,
  penalty_level: blacklisted ? 'SUSPENDED' : updatedCancellationRate > 0.15 ? 'WARNING_LEVEL_2' : 'WARNING_LEVEL_1',
  penalty_note: blacklisted
    ? `${data.provider_name} SUSPENDED — cancellation rate exceeded 30%.`
    : `Strike added. Rate: ${(updatedCancellationRate * 100).toFixed(0)}%.`,
  matching_score_delta: blacklisted ? -100 : -20,
  logged_at: now.toISOString()
};

console.log('=== WF7 Penalty Engine ===');
console.log('Provider:', data.provider_name, '| Rate:', existingCancellationRate, '->', updatedCancellationRate);

return [{ json: { ...data, penalty_record: penaltyRecord } }];

