// WF7 — USER CANCEL ONLY HANDLER
const data = $input.first().json;
const now = new Date();
console.log('=== WF7 User Cancel Only ===');
console.log('Booking:', data.booking_id, '| Provider:', data.provider_name);
return [{ json: {
  ...data,
  cancel_only_mode: true,
  cancelled_at: now.toISOString()
}}];

// ============================================================
// WF7 — INTAKE & VALIDATOR (FINAL MERGED)
// Handles: user cancel_only | user reschedule | provider_cancel
// ============================================================

const body = $input.first().json.body || $input.first().json;

const required = [
  'booking_id',
  'provider_id',
  'provider_name',
  'service_type',
  'location',
  'booking_date',
  'slot',
  'price_pkr'
];

const missing = required.filter(f => !body[f]);

if (missing.length > 0) {
  return [{
    json: {
      status: 'validation_error',
      message: `Missing required fields: ${missing.join(', ')}`,
      received: body,
      workflow: 'WF7-Intake'
    }
  }];
}

// ============================================================
// Convert 12h slot -> 24h (safe — handles both formats)
// ============================================================
function convertTo24Hour(timeStr) {
  if (!timeStr) return '09:00:00';
  // Already 24h format like '09:00' or '09:00:00'
  if (!timeStr.includes('AM') && !timeStr.includes('PM')) {
    const parts = timeStr.split(':');
    return `${String(parseInt(parts[0])).padStart(2,'0')}:${parts[1] || '00'}:00`;
  }
  const [time, modifier] = timeStr.trim().split(' ');
  let [hours, minutes] = time.split(':');
  hours = parseInt(hours, 10);
  if (modifier === 'PM' && hours !== 12) hours += 12;
  if (modifier === 'AM' && hours === 12) hours = 0;
  return `${String(hours).padStart(2, '0')}:${minutes || '00'}:00`;
}

const slot24 = convertTo24Hour(body.slot);
const bookingDateTime = new Date(`${body.booking_date}T${slot24}`);
const now = new Date();
const hoursUntilBooking = parseFloat(((bookingDateTime - now) / 3600000).toFixed(1));
const isUrgent = hoursUntilBooking < 3;
const isPast = hoursUntilBooking < 0;

// Normalise action and initiator
const action = body.action || 'reschedule';
const initiator = body.initiator || 'user';

console.log('=== WF7 Intake ===');
console.log('Booking:', body.booking_id);
console.log('Action:', action, '| Initiator:', initiator);
console.log('Slot:', body.slot, '->', slot24);
console.log('Hours Until Booking:', hoursUntilBooking);

return [{
  json: {
    ...body,
    action,
    initiator,
    slot24,
    hours_until_booking: hoursUntilBooking,
    is_urgent: isUrgent,
    is_past: isPast,
    alternatives: body.alternatives || [],
    user_name: body.user_name || 'Valued Customer',
    cancellation_reason_by_provider: body.cancellation_reason_by_provider || ''
  }
}];
